import { computed, watch, type ComputedRef, type Ref } from 'vue'
import { useErrorToast, useModuleT, useNuxtApp, useState } from '#imports'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by this module's `setup()`
import { useSavedDashboardLayouts, useUserSession } from '#dashboard/optional'
import type { DashboardLayout } from '../../../types'
import { normalizeLayout, pruneLayout } from '../../shared/layout'
import { getDashboardItemIds } from '../utils/components'

type Layouts = Record<string, DashboardLayout>

/** This session's layout changes, for one user (`owner`): dropped as soon as another user signs in. */
interface SessionLayouts {
  owner: string
  /** Every change made in this session, by dashboard name. Wins over the saved preference. */
  layouts: Layouts
  /** `layouts` as of the last successful save: what a failed save rolls back to. */
  confirmed: Layouts
}

/** One save in flight per app; changes made meanwhile are coalesced into the next one. */
interface Writer {
  running: Promise<void> | null
  dirty: boolean
}
const writers = new WeakMap<object, Writer>()

export interface DashboardLayoutState {
  /** The user's layout of this dashboard: this session's changes, else the saved preference, else the default. */
  layout: ComputedRef<DashboardLayout>
  /** Whether changes are saved for the user (Preferences, a cookie session, signed in), not only for this session. */
  persisted: ComputedRef<boolean>
  /** Resolves once the saved layouts are loaded (at once when they are not saved). */
  ready: Promise<void>
  /** Whether a save is in flight. */
  saving: Ref<boolean>
  /**
   * Applies a change (ids that are not items of the dashboard are dropped), then saves it for the user when it can. A
   * failed save shows an error toast and rolls the change back.
   */
  update: (change: (layout: DashboardLayout) => DashboardLayout) => Promise<void>
}

/**
 * The per-user layout of one dashboard. With `@frigear-nu/preferences`, Auth in server mode and a signed-in user it is
 * the `dashboardLayouts` preference, read and written through `/api/dashboard/me/layouts` (it is `managed`, so never in
 * the session cookie); otherwise it lives in `useState` for the session (keyed by user) and the registered default
 * applies again on reload.
 */
export function useDashboardLayout(name: string): DashboardLayoutState {
  const nuxtApp = useNuxtApp()
  const t = useModuleT('dashboard')
  const showError = useErrorToast()
  const state = useState<SessionLayouts>('dashboard:layouts', () => ({ owner: 'anon', layouts: {}, confirmed: {} }))
  const saving = useState<boolean>('dashboard:saving', () => false)
  const store = useSavedDashboardLayouts?.()
  const userSession = useUserSession?.()

  const owner = computed(() => {
    const id = userSession?.loggedIn.value ? userSession.user.value?.id : undefined
    return id === undefined || id === null ? 'anon' : `user:${id}`
  })
  const session = computed<Layouts>(() => state.value.owner === owner.value ? state.value.layouts : {})
  const persisted = computed(() => !!store && !!userSession?.loggedIn.value)
  const saved = computed<Layouts>(() => persisted.value ? store!.layouts(owner.value) : {})
  const layout = computed(() => normalizeLayout(session.value[name] ?? saved.value[name]))

  // The saved layouts of the signed-in user: loaded once, again when another user signs in.
  const load = () => persisted.value ? store!.load(owner.value) : Promise.resolve()
  const ready = load()
  watch(owner, () => {
    void load()
  })

  /** The session state of the current user, starting over when the user changed. */
  const own = (): SessionLayouts => state.value.owner === owner.value
    ? state.value
    : { owner: owner.value, layouts: {}, confirmed: {} }

  async function save(): Promise<void> {
    let writer = writers.get(nuxtApp)
    if (!writer) writers.set(nuxtApp, writer = { running: null, dirty: false })
    writer.dirty = true
    if (writer.running) return writer.running
    const current = writer
    current.running = (async () => {
      saving.value = true
      try {
        while (current.dirty) {
          current.dirty = false
          const sent = { ...own().layouts }
          try {
            // Only the dashboards changed this session: the server merges them into what is stored (and drops a stored
            // layout that no longer parses), so the other dashboards are never sent back.
            await store!.save(owner.value, sent)
            state.value = { ...own(), confirmed: sent }
          }
          catch (error) {
            current.dirty = false
            const base = own()
            state.value = { ...base, layouts: { ...base.confirmed } }
            showError(error, t('save.error', 'Your dashboard layout could not be saved.'))
            return
          }
        }
      }
      finally {
        saving.value = false
        current.running = null
      }
    })()
    return current.running
  }

  async function update(change: (layout: DashboardLayout) => DashboardLayout) {
    const next = pruneLayout(change(layout.value), getDashboardItemIds(name))
    const base = own()
    const layouts = { ...base.layouts, [name]: next }
    // Without saving, the session copy is all there is: nothing to roll back to.
    state.value = { ...base, layouts, confirmed: persisted.value ? base.confirmed : layouts }
    if (persisted.value) await save()
  }

  return { layout, persisted, ready, saving, update }
}
